from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover an H×W grid.

    Tiles may be rotated, each available tile may be used at most once, and tiles
    must be aligned to cells and remain within the grid.
    """
    if h <= 0 or w <= 0 or n < 0 or len(tiles) < n:
        return False
    tiles = tiles[:n]
    if any(a <= 0 or b <= 0 for a, b in tiles):
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]

    # A placement anchored at the first uncovered cell is sufficient: any
    # placement covering that cell and starting earlier would overlap an
    # already covered cell.
    @lru_cache(maxsize=None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True

        uncovered = full ^ occupied
        first = (uncovered & -uncovered).bit_length() - 1
        row, col = divmod(first, w)
        blanks = uncovered.bit_count()

        # The areas of some subset of the remaining tiles must equal the
        # number of cells still to be covered.
        possible = {0}
        bits = remaining
        while bits:
            bit = bits & -bits
            idx = bit.bit_length() - 1
            area = areas[idx]
            possible |= {s + area for s in possible if s + area <= blanks}
            bits ^= bit
        if blanks not in possible:
            return False

        seen_shapes = set()
        bits = remaining
        while bits:
            bit = bits & -bits
            idx = bit.bit_length() - 1
            bits ^= bit
            a, b = tiles[idx]
            orientations = {(a, b), (b, a)}
            for rh, rw in orientations:
                if (rh, rw) in seen_shapes:
                    continue
                if row + rh > h or col + rw > w:
                    continue

                mask = 0
                row_bits = ((1 << rw) - 1) << col
                for rr in range(row, row + rh):
                    mask |= row_bits << (rr * w)
                if occupied & mask:
                    continue
                seen_shapes.add((rh, rw))
                if search(occupied | mask, remaining ^ bit):
                    return True
        return False

    return search(0, (1 << n) - 1)

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding paths of K moves through empty grid cells."""
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == "."]
    if len(cells) < K + 1:
        return 0

    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        adjacent = []
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            j = index.get((nr, nc))
            if j is not None:
                adjacent.append(j)
        neighbors.append(adjacent)

    total = 0

    def extend(current: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        count = 0
        for nxt in neighbors[current]:
            bit = 1 << nxt
            if not visited & bit:
                count += extend(nxt, remaining - 1, visited | bit)
        return count

    for start in range(len(cells)):
        total += extend(start, K, 1 << start)
    return total

from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Find a non-empty subsequence with alternating sum k and maximal product <= limit.

    The alternating sum is the sum at even selected indices minus the sum at odd
    selected indices. The product includes every selected element.
    """
    # The absolute alternating sum cannot exceed the sum of all input values.
    if abs(k) > sum(nums):
        return -1

    # Each state records (alternating_sum, selected_length_parity, product,
    # whether any element has been selected). The parity determines the sign of
    # the next selected value.
    states = {(0, 0, 1, False)}
    for value in nums:
        next_states = set(states)  # omit this input element
        for total, parity, product, nonempty in states:
            new_product = product * value
            if new_product <= limit:
                new_total = total + value if parity == 0 else total - value
                next_states.add((new_total, 1 - parity, new_product, True))
        states = next_states

    answers = (product for total, _, product, nonempty in states
               if total == k and nonempty)
    return max(answers, default=-1)

from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is
    divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]
    """

    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0

        digits = tuple(map(int, str(bound)))
        total = 0

        # Handle each possible number length separately, so leading zeroes
        # never become part of a number's digit product.
        for length in range(1, len(digits) + 1):
            limit_digits = digits if length == len(digits) else (9,) * length
            max_sum = 9 * length

            for target_sum in range(1, max_sum + 1):
                @lru_cache(maxsize=None)
                def visit(pos: int, digit_sum: int, product_mod: int, tight: bool) -> int:
                    if digit_sum > target_sum or digit_sum + 9 * (length - pos) < target_sum:
                        return 0
                    if pos == length:
                        return int(digit_sum == target_sum and product_mod == 0)

                    low = 1 if pos == 0 else 0
                    high = limit_digits[pos] if tight else 9
                    result = 0
                    for digit in range(low, high + 1):
                        result += visit(
                            pos + 1,
                            digit_sum + digit,
                            (product_mod * digit) % target_sum,
                            tight and digit == high,
                        )
                    return result

                total += visit(0, 0, 1 % target_sum, True)

        return total

    return count_up_to(r) - count_up_to(l - 1)

