from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether the grid can be exactly covered by the available tiles.

    Tiles may be rotated, each may be used at most once, and placements must
    align with cells and stay inside the grid.
    """
    if h <= 0 or w <= 0 or n < 0 or len(tiles) < n:
        return False
    tiles = tiles[:n]
    if any(a <= 0 or b <= 0 for a, b in tiles):
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]

    @lru_cache(maxsize=None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True

        uncovered = full ^ occupied
        first = (uncovered & -uncovered).bit_length() - 1
        row, col = divmod(first, w)
        blanks = uncovered.bit_count()

        # Discard states where no subset of remaining tile areas fits exactly.
        area_sums = {0}
        for i in range(n):
            if remaining & (1 << i):
                area = areas[i]
                area_sums |= {total + area for total in area_sums
                              if total + area <= blanks}
        if blanks not in area_sums:
            return False

        tried_tiles = set()
        for i in range(n):
            bit = 1 << i
            if not remaining & bit:
                continue
            shape = tuple(sorted(tiles[i]))
            if shape in tried_tiles:
                continue
            tried_tiles.add(shape)

            a, b = tiles[i]
            for rh, rw in {(a, b), (b, a)}:
                if row + rh > h or col + rw > w:
                    continue

                mask = 0
                row_mask = ((1 << rw) - 1) << col
                for rr in range(row, row + rh):
                    mask |= row_mask << (rr * w)
                if occupied & mask:
                    continue
                if search(occupied | mask, remaining ^ bit):
                    return True
        return False

    return search(0, (1 << n) - 1)

