from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Determine the winner of the card game under optimal play.

    A move plays a card and takes a table card whose value is no greater
    than the played card. The played card remains on the table. A player
    with no such move loses.
    """
    first_hand = tuple(sorted(takahashi_cards))
    second_hand = tuple(sorted(aoki_cards))
    initial_table = tuple(sorted(table_cards))

    @lru_cache(maxsize=None)
    def winning(hand_a: Tuple[int, ...], hand_b: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = hand_a if turn == 0 else hand_b
        if not hand:
            return False

        for i, played in enumerate(hand):
            next_hand = hand[:i] + hand[i + 1:]
            # Capture one table card no larger than the card just played.
            for j, captured in enumerate(table):
                if captured <= played:
                    next_table = tuple(sorted(table[:j] + table[j + 1:] + (played,)))
                    if turn == 0:
                        opponent_wins = winning(next_hand, hand_b, next_table, 1)
                    else:
                        opponent_wins = winning(hand_a, next_hand, next_table, 0)
                    if not opponent_wins:
                        return True
        return False

    return "Takahashi" if winning(first_hand, second_hand, initial_table, 0) else "Aoki"

def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equally many even and odd digits
    that are divisible by k.
    """
    def count_up_to(limit: int) -> int:
        if limit <= 0:
            return 0
        digits = str(limit)
        total = 0

        # Equal counts require an even number of digits. Handle each digit
        # length separately so leading zeroes are never part of a number.
        for length in range(2, len(digits) + 1, 2):
            bound = digits if length == len(digits) else "9" * length
            bound_digits = [int(ch) for ch in bound]
            # State is (remainder modulo k, odd-minus-even count, tight).
            states = {(0, 0, True): 1}
            for pos, max_digit in enumerate(bound_digits):
                next_states = {}
                for (remainder, balance, tight), ways in states.items():
                    upper = max_digit if tight else 9
                    lower = 1 if pos == 0 else 0
                    for digit in range(lower, upper + 1):
                        new_tight = tight and digit == max_digit
                        new_remainder = (remainder * 10 + digit) % k
                        new_balance = balance + (1 if digit % 2 else -1)
                        key = (new_remainder, new_balance, new_tight)
                        next_states[key] = next_states.get(key, 0) + ways
                states = next_states
            total += states.get((0, 0, False), 0)
            total += states.get((0, 0, True), 0)
        return total

    return count_up_to(high) - count_up_to(low - 1)

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Return whether the H×W grid can be exactly covered by available tiles.

    Each rectangular tile can be rotated and used at most once. Tiles must be
    aligned to grid cells and fit entirely inside the grid.
    """
    if h <= 0 or w <= 0 or n < 0 or len(tiles) < n:
        return False
    tiles = tiles[:n]
    if any(a <= 0 or b <= 0 for a, b in tiles):
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]

    @lru_cache(maxsize=None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True

        uncovered = full ^ occupied
        first = (uncovered & -uncovered).bit_length() - 1
        row, col = divmod(first, w)
        blanks = uncovered.bit_count()

        area_sums = {0}
        for i in range(n):
            if remaining & (1 << i):
                area = areas[i]
                area_sums |= {total + area for total in area_sums
                              if total + area <= blanks}
        if blanks not in area_sums:
            return False

        tried_tiles = set()
        for i, (a, b) in enumerate(tiles):
            bit = 1 << i
            if not remaining & bit:
                continue
            shape = tuple(sorted((a, b)))
            if shape in tried_tiles:
                continue
            tried_tiles.add(shape)

            for rh, rw in {(a, b), (b, a)}:
                # Enumerate every placement containing the first uncovered
                # cell; placements overlapping earlier cells are rejected.
                min_r = max(0, row - rh + 1)
                max_r = min(row, h - rh)
                min_c = max(0, col - rw + 1)
                max_c = min(col, w - rw)
                for top in range(min_r, max_r + 1):
                    for left in range(min_c, max_c + 1):
                        mask = 0
                        row_mask = ((1 << rw) - 1) << left
                        for rr in range(top, top + rh):
                            mask |= row_mask << (rr * w)
                        if not (mask & (1 << first)) or occupied & mask:
                            continue
                        if search(occupied | mask, remaining ^ bit):
                            return True
        return False

    return search(0, (1 << n) - 1)

