from math import isqrt


def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a**b for positive a and b >= 2."""
    # Every square is counted directly. Enumerate higher powers and retain
    # only nonsquares, so powers with several exponent representations remain
    # counted once and squares are not counted twice.
    nonsquare_powers = set()
    a = 2
    while a * a * a <= n:
        value = a * a * a
        while value <= n:
            if isqrt(value) ** 2 != value:
                nonsquare_powers.add(value)
            value *= a
        a += 1
    return isqrt(n) + len(nonsquare_powers)

