def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in the inclusive range whose digit sum is within bounds."""
    mod = 1_000_000_007

    def count_at_most(bound: str, limit: int) -> int:
        if limit < 0:
            return 0
        # dp[s] counts prefixes already smaller than bound with digit sum s.
        dp = [0] * (limit + 1)
        dp[0] = 1
        tight_sum = 0
        for ch in bound:
            digit = ord(ch) - ord("0")
            nxt = [0] * (limit + 1)
            for total, ways in enumerate(dp):
                if ways:
                    upto = min(9, limit - total)
                    for d in range(upto + 1):
                        nxt[total + d] = (nxt[total + d] + ways) % mod
            # The still-tight prefix can become smaller at this position.
            for d in range(min(digit, limit - tight_sum + 1)):
                total = tight_sum + d
                if total <= limit:
                    nxt[total] = (nxt[total] + 1) % mod
            tight_sum += digit
            dp = nxt
        answer = sum(dp) % mod
        if tight_sum <= limit:
            answer = (answer + 1) % mod
        return answer

    def decrement(value: str) -> str | None:
        digits = list(value)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        result = "".join(digits).lstrip("0")
        return result or "0"

    def range_count(upper: str, lower: str) -> int:
        below_lower = decrement(lower)
        hi = count_at_most(upper, max_sum) - count_at_most(upper, min_sum - 1)
        if below_lower is not None:
            hi -= count_at_most(below_lower, max_sum) - count_at_most(below_lower, min_sum - 1)
        return hi % mod

    return range_count(num2, num1)

