from array import array

MOD = 998244353


def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings extending the given clues, modulo 998244353."""
    if W > H:
        lines = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        width = H
    else:
        lines = grid
        width = W

    # A transfer state is one coloring of a short line. Store every base-3
    # assignment in a packed array; states violating horizontal edges stay zero.
    size = 3 ** width
    states = []

    def build(pos: int, prev: int, code: int, digits: tuple[int, ...]) -> None:
        if pos == width:
            states.append((code, digits))
            return
        for color in range(3):
            if color != prev:
                build(pos + 1, color, code + color * (3 ** pos), digits + (color,))

    build(0, -1, 0, ())
    values = array("I", [0]) * size

    def allowed_codes(line: str):
        for code, digits in states:
            if all(ch == "?" or ord(ch) - 49 == color
                   for ch, color in zip(line, digits)):
                yield code

    for code in allowed_codes(lines[0]):
        values[code] = 1

    for line in lines[1:]:
        # Apply the tensor product of the 3x3 matrix whose off-diagonal
        # entries are one. This sums all previous states differing at each cell.
        stride = 1
        for _ in range(width):
            block = stride * 3
            for start in range(0, size, block):
                for offset in range(stride):
                    i0 = start + offset
                    i1 = i0 + stride
                    i2 = i1 + stride
                    x0, x1, x2 = values[i0], values[i1], values[i2]
                    values[i0] = x1 + x2
                    values[i1] = x0 + x2
                    values[i2] = x0 + x1
            stride = block

        allowed = bytearray(size)
        for code in allowed_codes(line):
            allowed[code] = 1
        for code in range(size):
            if not allowed[code]:
                values[code] = 0
            else:
                values[code] %= MOD

    return sum(values[code] for code, _ in states) % MOD

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in the inclusive range whose digit sum is within bounds."""
    mod = 1_000_000_007

    def count_at_most(bound: str, limit: int) -> int:
        if limit < 0:
            return 0
        dp = [0] * (limit + 1)  # prefixes already smaller than the bound
        tight_sum = 0
        for ch in bound:
            digit = ord(ch) - ord("0")
            nxt = [0] * (limit + 1)
            for total, ways in enumerate(dp):
                if ways:
                    for d in range(min(9, limit - total) + 1):
                        nxt[total + d] = (nxt[total + d] + ways) % mod
            for d in range(min(digit, limit - tight_sum + 1)):
                total = tight_sum + d
                if total <= limit:
                    nxt[total] = (nxt[total] + 1) % mod
            tight_sum += digit
            dp = nxt
        answer = sum(dp) % mod
        if tight_sum <= limit:
            answer = (answer + 1) % mod
        return answer

    def decrement(value: str) -> str | None:
        digits = list(value)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        return "".join(digits).lstrip("0") or "0"

    def count_range(upper: str, lower: str) -> int:
        below = decrement(lower)
        result = count_at_most(upper, max_sum) - count_at_most(upper, min_sum - 1)
        if below is not None:
            result -= count_at_most(below, max_sum) - count_at_most(below, min_sum - 1)
        return result % mod

    return count_range(num2, num1)

