from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """ Given an array of coin denominations and an integer k, return the k-th smallest amount
    that can be made using these coins. You have infinite coins of each denomination, but
    cannot combine coins of different denominations in a single amount.

    Each coin denomination produces its multiples (e.g., coin 3 produces 3, 6, 9, 12, ...).
    The k-th smallest among all possible amounts from all denominations is returned.

    Args:
        coins: List of distinct positive integers representing coin denominations (1-15 elements, each 1-25)
        k: The position of the desired amount (1-based indexing, 1 <= k <= 2*10^9)

    Returns:
        The k-th smallest amount that can be made

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Inclusion-exclusion over divisibility sets gives the number of distinct
    # amounts at most x. Aggregate subsets with the same LCM to keep each
    # binary-search count compact.
    coefficients = {}
    for coin in coins:
        additions = {coin: 1}
        for common_multiple, coefficient in coefficients.items():
            lcm = common_multiple // gcd(common_multiple, coin) * coin
            additions[lcm] = additions.get(lcm, 0) - coefficient
        for common_multiple, coefficient in additions.items():
            coefficients[common_multiple] = coefficients.get(common_multiple, 0) + coefficient
            if coefficients[common_multiple] == 0:
                del coefficients[common_multiple]

    def count_at_most(amount: int) -> int:
        return sum(coefficient * (amount // common_multiple)
                   for common_multiple, coefficient in coefficients.items()
                   if common_multiple <= amount)

    low, high = 1, min(coins) * k
    while low < high:
        middle = (low + high) // 2
        if count_at_most(middle) >= k:
            high = middle
        else:
            low = middle + 1
    return low

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """ Given two strings s and t of length n consisting of 'B' and 'W' characters,
    determine the minimum number of operations needed to transform the initial configuration s
    into the target configuration t.

    Initially, there are n stones placed in cells 1 to n according to string s,
    where 'W' represents a white stone and 'B' represents a black stone.
    There are also two empty cells at positions n+1 and n+2.

    In one operation, you can:
    - Choose two adjacent cells that both contain stones
    - Move these two stones to the two empty cells while preserving their order

    Return the minimum number of operations needed to achieve configuration t,
    or -1 if it's impossible.

    Args:
        n: Number of stones (2 <= n <= 14)
        s: Initial configuration string of length n
        t: Target configuration string of length n

    Returns:
        Minimum number of operations, or -1 if impossible
    """
    if len(s) != n or len(t) != n or s.count("B") != t.count("B"):
        return -1
    start = s + ".."
    goal = t + ".."
    if start == goal:
        return 0

    # Search forward from the initial arrangement and backward from the goal.
    # A state stores all cells, with '.' marking the two empty cells.
    forward = {start: 0}
    backward = {goal: 0}
    f_front = {start}
    b_front = {goal}

    def successors(state):
        holes = [i for i, ch in enumerate(state) if ch == "."]
        chars = list(state)
        for i in range(n + 1):
            if state[i] != "." and state[i + 1] != ".":
                a, b = state[i], state[i + 1]
                nxt = chars.copy()
                nxt[i] = nxt[i + 1] = "."
                nxt[holes[0]], nxt[holes[1]] = a, b
                yield "".join(nxt)

    def predecessors(state):
        holes = [i for i, ch in enumerate(state) if ch == "."]
        occupied = [i for i, ch in enumerate(state) if ch != "."]
        # The two current holes were the adjacent source cells in the prior state.
        for i in range(n + 1):
            if state[i] == "." and state[i + 1] == ".":
                for x in range(n + 2):
                    if state[x] == ".":
                        continue
                    for y in range(x + 1, n + 2):
                        if state[y] == ".":
                            continue
                        nxt = list(state)
                        a, b = state[x], state[y]
                        nxt[i], nxt[i + 1] = a, b
                        nxt[x] = nxt[y] = "."
                        yield "".join(nxt)

    while f_front and b_front:
        expand_forward = len(f_front) <= len(b_front)
        if expand_forward:
            next_front = set()
            for state in f_front:
                distance = forward[state] + 1
                for nxt in successors(state):
                    if nxt not in forward:
                        forward[nxt] = distance
                        if nxt in backward:
                            return distance + backward[nxt]
                        next_front.add(nxt)
            f_front = next_front
        else:
            next_front = set()
            for state in b_front:
                distance = backward[state] + 1
                for prev in predecessors(state):
                    if prev not in backward:
                        backward[prev] = distance
                        if prev in forward:
                            return distance + forward[prev]
                        next_front.add(prev)
            b_front = next_front
    return -1

MOD = 998244353


def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings of the grid consistent with its fixed cells."""
    # Work across the shorter dimension so the row-state frontier stays small.
    if W <= H:
        rows = [tuple(row) for row in grid]
    else:
        rows = [tuple(grid[r][c] for r in range(H)) for c in range(W)]

    width = len(rows[0])

    def row_states(fixed):
        result = []

        def build(col, state):
            if col == width:
                result.append(tuple(state))
                return
            choices = (int(fixed[col]),) if fixed[col] != "?" else (1, 2, 3)
            for value in choices:
                if col == 0 or value != state[-1]:
                    state.append(value)
                    build(col + 1, state)
                    state.pop()

        build(0, [])
        return result

    dp = {state: 1 for state in row_states(rows[0])}
    if not dp:
        return 0

    # Cache transition lists by source state and destination row clues.
    transition_cache = {}
    for fixed in rows[1:]:
        next_dp = {}
        for source, count in dp.items():
            key = (source, fixed)
            targets = transition_cache.get(key)
            if targets is None:
                found = []
                out = []

                def build(col):
                    if col == width:
                        found.append(tuple(out))
                        return
                    choices = (int(fixed[col]),) if fixed[col] != "?" else (1, 2, 3)
                    for value in choices:
                        if value == source[col]:
                            continue
                        if col and value == out[-1]:
                            continue
                        out.append(value)
                        build(col + 1)
                        out.pop()

                build(0)
                targets = tuple(found)
                transition_cache[key] = targets
            for target in targets:
                next_dp[target] = (next_dp.get(target, 0) + count) % MOD
        dp = next_dp
        if not dp:
            return 0
    return sum(dp.values()) % MOD

from itertools import product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose sole missing length-M subsequence is X."""
    target = tuple(X)
    total = 0
    # Build the set of length-M subsequences incrementally for each candidate.
    for word in product(range(1, K + 1), repeat=N):
        matched = {()}
        for value in word:
            matched.update(prefix + (value,) for prefix in tuple(matched) if len(prefix) < M)
        if len(matched) == K ** M:
            continue
        if target not in matched and len(matched) == K ** M - 1:
            total += 1
    return total % MOD

from functools import lru_cache
from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Return the winner of the index-marking game under optimal play."""
    # A selected index can be played again only as a wasted move.  Such moves
    # are represented by the pool of remaining counters on already marked
    # indices.
    @lru_cache(None)
    def winning(rem: tuple, spare: int) -> bool:
        if len(rem) == 1:
            # Marking the final index wins immediately.
            return True
        # Beyond this bound, only the parity of the spare moves is relevant:
        # outcomes repeat as players alternate consuming spare moves.
        threshold = 2 * (len(rem) + 1)
        if spare > threshold:
            spare = threshold + (spare - threshold) % 2
        if spare and not winning(rem, spare - 1):
            return True
        for j, value in enumerate(rem):
            nxt = rem[:j] + rem[j + 1:]
            if not winning(nxt, spare + value - 1):
                return True
        return False

    # Initial move must mark one index. If it is the only index, it wins.
    if n == 1:
        return "Fennec"
    for j, value in enumerate(a):
        rem = tuple(a[:j] + a[j + 1:])
        if not winning(rem, value - 1):
            return "Fennec"
    return "Snuke"

