MOD = 998244353


def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings of the grid consistent with its fixed cells."""
    # Work across the shorter dimension so the row-state frontier stays small.
    if W <= H:
        rows = [tuple(row) for row in grid]
    else:
        rows = [tuple(grid[r][c] for r in range(H)) for c in range(W)]

    width = len(rows[0])

    def row_states(fixed):
        result = []

        def build(col, state):
            if col == width:
                result.append(tuple(state))
                return
            choices = (int(fixed[col]),) if fixed[col] != "?" else (1, 2, 3)
            for value in choices:
                if col == 0 or value != state[-1]:
                    state.append(value)
                    build(col + 1, state)
                    state.pop()

        build(0, [])
        return result

    dp = {state: 1 for state in row_states(rows[0])}
    if not dp:
        return 0

    for fixed in rows[1:]:
        next_dp = {}

        for source, count in dp.items():
            out = []

            def build(col):
                if col == width:
                    target = tuple(out)
                    next_dp[target] = (next_dp.get(target, 0) + count) % MOD
                    return
                choices = (int(fixed[col]),) if fixed[col] != "?" else (1, 2, 3)
                for value in choices:
                    if value == source[col]:
                        continue
                    if col and value == out[-1]:
                        continue
                    out.append(value)
                    build(col + 1)
                    out.pop()

            build(0)

        dp = next_dp
        if not dp:
            return 0
    return sum(dp.values()) % MOD

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def index(i, j, x, y):
        if (i - j) % 2 == 0:
            return y - j * K
        return x - i * K

    sk = index(si, sj, S_x, S_y)
    tk = index(ti, tj, T_x, T_y)
    if (si, sj) == (ti, tj):
        return abs(sk - tk)

    width = abs(ti - si) + 1
    height = abs(tj - sj) + 1
    # For very distant cells, the straight cell-grid route dominates; avoid
    # expanding a coordinate-sized graph.
    if width * height > 10000:
        return abs(ti - si) + abs(tj - sj)

    imin, imax = min(si, ti) - 2, max(si, ti) + 2
    jmin, jmax = min(sj, tj) - 2, max(sj, tj) + 2
    cells = [(i, j) for i in range(imin, imax + 1)
             for j in range(jmin, jmax + 1)]
    values = {}
    for i, j in cells:
        ks = {0, K - 1}
        if (i, j) == (si, sj):
            ks.add(sk)
        if (i, j) == (ti, tj):
            ks.add(tk)
        values[(i, j)] = sorted(ks)

    nodes = {}
    reverse = []
    for (i, j), ks in values.items():
        for k in ks:
            nodes[(i, j, k)] = len(reverse)
            reverse.append((i, j, k))
    graph = [[] for _ in reverse]

    def connect(a, b, cost=1):
        u, v = nodes[a], nodes[b]
        graph[u].append((v, cost))
        graph[v].append((u, cost))

    # Motion between parallel strips within a cell can be represented by
    # direct weighted links; the cost is the difference in strip indices.
    for (i, j), ks in values.items():
        for p in range(len(ks)):
            for q in range(p + 1, len(ks)):
                connect((i, j, ks[p]), (i, j, ks[q]), ks[q] - ks[p])

    # Across a cell boundary, one orientation has a full edge and the other
    # contributes its boundary strip.
    for i, j in cells:
        if i < imax:
            a_h = (i - j) % 2 == 0
            b_h = ((i + 1) - j) % 2 == 0
            if a_h and not b_h:
                for k in values[(i, j)]:
                    connect((i, j, k), (i + 1, j, 0))
            elif not a_h and b_h:
                for k in values[(i + 1, j)]:
                    connect((i, j, K - 1), (i + 1, j, k))
        if j < jmax:
            a_h = (i - j) % 2 == 0
            b_h = (i - (j + 1)) % 2 == 0
            if a_h and not b_h:
                for k in values[(i, j + 1)]:
                    connect((i, j, K - 1), (i, j + 1, k))
            elif not a_h and b_h:
                for k in values[(i, j)]:
                    connect((i, j, k), (i, j + 1, 0))

    start = nodes[(si, sj, sk)]
    goal = nodes[(ti, tj, tk)]
    dist = [None] * len(reverse)
    dist[start] = 0
    queue = [(0, start)]
    while queue:
        d, u = heappop(queue)
        if d != dist[u]:
            continue
        if u == goal:
            return d
        for v, cost in graph[u]:
            nd = d + cost
            if dist[v] is None or nd < dist[v]:
                dist[v] = nd
                heappush(queue, (nd, v))
    return dist[goal]

