def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353
    """
    MOD = 998244353

    # Transfer across the shorter dimension. A row state is encoded as a
    # base-3 integer, with digits 0, 1, 2 representing colors 1, 2, 3.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    allowed = []
    for row in grid:
        allowed.append([
            (0, 1, 2) if ch == '?' else (ord(ch) - ord('1'),)
            for ch in row
        ])

    # Enumerate horizontally valid states for each row, honoring its clues.
    row_states = []
    for row_allowed in allowed:
        states = []
        def build_row(col, prev, code):
            if col == W:
                states.append(code)
                return
            for color in row_allowed[col]:
                if color != prev:
                    build_row(col + 1, color, code * 3 + color)
        build_row(0, -1, 0)
        row_states.append(states)

    # Decode only the current layer's possible states to color vectors.
    def decode(code):
        colors = [0] * W
        for i in range(W - 1, -1, -1):
            colors[i] = code % 3
            code //= 3
        return colors

    dp = {code: 1 for code in row_states[0]}
    for r in range(1, H):
        next_allowed = allowed[r]
        next_states = set(row_states[r])
        nxt = {}
        for upper_code, count in dp.items():
            upper = decode(upper_code)

            def extend(col, prev, code):
                if col == W:
                    if code in next_states:
                        nxt[code] = (nxt.get(code, 0) + count) % MOD
                    return
                for color in next_allowed[col]:
                    if color != prev and color != upper[col]:
                        extend(col + 1, color, code * 3 + color)

            extend(0, -1, 0)
        dp = nxt
        if not dp:
            return 0

    return sum(dp.values()) % MOD

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the minimum adjacency moves between the tiles containing the given points."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def get_k(i, j, x, y):
        return y - j * K if (i - j) % 2 == 0 else x - i * K

    sk, tk = get_k(si, sj, S_x, S_y), get_k(ti, tj, T_x, T_y)
    width, height = abs(ti - si) + 1, abs(tj - sj) + 1
    if width * height > 10000:
        return abs(ti - si) + abs(tj - sj)

    pad = 10
    imin, imax = min(si, ti) - pad, max(si, ti) + pad
    jmin, jmax = min(sj, tj) - pad, max(sj, tj) + pad
    vals = {}
    for i in range(imin, imax + 1):
        for j in range(jmin, jmax + 1):
            ks = {0, K - 1}
            if (i, j) == (si, sj):
                ks.add(sk)
            if (i, j) == (ti, tj):
                ks.add(tk)
            vals[i, j] = sorted(ks)

    ids, coords = {}, []
    for (i, j), ks in vals.items():
        for k in ks:
            ids[i, j, k] = len(coords)
            coords.append((i, j, k))
    graph = [[] for _ in coords]

    def link(a, b, cost=1):
        u, v = ids[a], ids[b]
        graph[u].append((v, cost))
        graph[v].append((u, cost))

    for (i, j), ks in vals.items():
        for p, k in enumerate(ks):
            for z in ks[p + 1:]:
                link((i, j, k), (i, j, z), z - k)

    for i in range(imin, imax + 1):
        for j in range(jmin, jmax + 1):
            ah = (i - j) % 2 == 0
            if i < imax:
                if ah:
                    for k in vals[i, j]:
                        link((i, j, k), (i + 1, j, 0))
                else:
                    for k in vals[i + 1, j]:
                        link((i, j, K - 1), (i + 1, j, k))
            if j < jmax:
                if ah:
                    for k in vals[i, j + 1]:
                        link((i, j, K - 1), (i, j + 1, k))
                else:
                    for k in vals[i, j]:
                        link((i, j, k), (i, j + 1, 0))

    start, goal = ids[si, sj, sk], ids[ti, tj, tk]
    dist = [None] * len(coords)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == goal:
            return d
        for v, c in graph[u]:
            nd = d + c
            if dist[v] is None or nd < dist[v]:
                dist[v] = nd
                heappush(heap, (nd, v))
    return dist[goal]

def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma(n) divisible by 3."""
    MOD = 998244353
    if N < 1 or M < 1:
        return 0

    # For n = product(p**e), the number of ordered length-M factorizations is
    # prod C(M+e-1, e).  Also sigma is multiplicative. Modulo 3 its prime
    # power factor is zero precisely for p == 2 (mod 3), e odd, or
    # p == 1 (mod 3), e == 2 (mod 3).
    limit = int(N ** 0.5)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, int(limit ** 0.5) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * (((limit - start) // p) + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    max_exp = N.bit_length()
    inv = [0] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        inv[e] = pow(e, MOD - 2, MOD)
    # C(M+e-1,e), for the small exponents possible under the bound.
    choose = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        choose[e] = choose[e - 1] * (M + e - 1) % MOD * inv[e] % MOD

    block_size = 100_000
    answer = 0
    for lo in range(1, N + 1, block_size):
        hi = min(N + 1, lo + block_size)
        rem = list(range(lo, hi))
        weights = [1] * (hi - lo)
        good = bytearray(b"\x00") * (hi - lo)
        for p in primes:
            if p * p >= hi:
                break
            first = ((lo + p - 1) // p) * p
            for x in range(first, hi, p):
                idx = x - lo
                e = 0
                while rem[idx] % p == 0:
                    rem[idx] //= p
                    e += 1
                if e:
                    weights[idx] = weights[idx] * choose[e] % MOD
                    if (p % 3 == 2 and e % 2 == 1) or (p % 3 == 1 and e % 3 == 2):
                        good[idx] = 1

        for idx, q in enumerate(rem):
            if q > 1:
                weights[idx] = weights[idx] * choose[1] % MOD
                if q % 3 == 2:
                    good[idx] = 1
        for idx, is_good in enumerate(good):
            if is_good:
                answer += weights[idx]
        answer %= MOD
    return answer

from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """ Count the number of length-M sequences of positive integers whose product is a "good integer" not exceeding N.

    A positive integer n is called a "good integer" if and only if the sum of its positive divisors is divisible by 3.

    The result should be returned modulo 998244353.

    Args:
        N: Upper bound for the product of elements in the sequence (1 <= N <= 10^10)
        M: Length of the sequences (1 <= M <= 10^5)

    Returns:
        The number of valid sequences modulo 998244353

    >>> count_good_sequences(10, 1)
    5
    >>> count_good_sequences(4, 2)
    2
    >>> count_good_sequences(370, 907)
    221764640
    """
    # Sieve primes once.  The local factor of sigma(p**e) modulo 3 is
    # 1 for p=3; e+1 for p == 1 (mod 3); and 1 for even e / 0 for odd e
    # when p == 2 (mod 3).
    limit = isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    answer = 0
    for value in range(2, N + 1):
        rem = value
        omega = 0
        sigma_residue = 1
        for p in primes:
            if p * p > rem:
                break
            if rem % p == 0:
                exponent = 0
                while rem % p == 0:
                    rem //= p
                    exponent += 1
                omega += exponent
                if p % 3 == 1:
                    sigma_residue = sigma_residue * (exponent + 1) % 3
                elif p % 3 == 2:
                    if exponent & 1:
                        sigma_residue = 0
        if rem > 1:
            omega += 1
            if rem % 3 == 1:
                sigma_residue = sigma_residue * 2 % 3
            elif rem % 3 == 2:
                sigma_residue = 0
        if sigma_residue == 0:
            # C(M + omega - 1, omega) counts distributions of each prime
            # exponent among the M ordered positions, so multiply one such
            # factor for every prime power in value.
            rem = value
            ways = 1
            for p in primes:
                if p * p > rem:
                    break
                if rem % p == 0:
                    exponent = 0
                    while rem % p == 0:
                        rem //= p
                        exponent += 1
                    ways = ways * _choose_small(M + exponent - 1, exponent) % MOD
            if rem > 1:
                ways = ways * M % MOD
            answer = (answer + ways) % MOD
    return answer


def _choose_small(n: int, k: int) -> int:
    result = 1
    for i in range(1, k + 1):
        result = result * (n - k + i) % MOD
        result = result * pow(i, MOD - 2, MOD) % MOD
    return result

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent-tile moves between the two points."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sh = (si + sj) % 2 == 0
    th = (ti + tj) % 2 == 0
    sk = S_y - sj * K if sh else S_x - si * K
    tk = T_y - tj * K if th else T_x - ti * K
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    stripes = list(range(K)) if K <= 200 else sorted({0, K - 1, sk, tk})
    count = len(stripes)
    width = abs(si - ti) + 5
    height = abs(sj - tj) + 5
    if width * height > 30000:
        return abs(si - ti) + abs(sj - tj)

    xmin, xmax = min(si, ti) - 2, max(si, ti) + 2
    ymin, ymax = min(sj, tj) - 2, max(sj, tj) + 2
    rows = ymax - ymin + 1

    def node(i, j, q):
        return ((i - xmin) * rows + (j - ymin)) * count + q

    start_q, target_q = stripes.index(sk), stripes.index(tk)
    start, goal = node(si, sj, start_q), node(ti, tj, target_q)
    dist = {start: 0}
    heap = [(0, si, sj, start_q)]
    infinity = 10**100

    while heap:
        d, i, j, q = heappop(heap)
        u = node(i, j, q)
        if d != dist.get(u):
            continue
        if u == goal:
            return d
        for r in (q - 1, q + 1):
            if 0 <= r < count and (stripes[r] - stripes[q]) in (-1, 1):
                v = node(i, j, r)
                if d + 1 < dist.get(v, infinity):
                    dist[v] = d + 1
                    heappush(heap, (d + 1, i, j, r))

        horizontal = (i + j) % 2 == 0
        for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            ni, nj = i + di, j + dj
            if not (xmin <= ni <= xmax and ymin <= nj <= ymax):
                continue
            if di:
                if horizontal:
                    required = 0 if di == 1 else K - 1
                    choices = (stripes.index(required),)
                else:
                    required = K - 1 if di == 1 else 0
                    if stripes[q] != required:
                        continue
                    choices = range(count)
            elif horizontal:
                required = K - 1 if dj == 1 else 0
                if stripes[q] != required:
                    continue
                choices = range(count)
            else:
                required = 0 if dj == 1 else K - 1
                choices = (stripes.index(required),)
            for r in choices:
                v = node(ni, nj, r)
                if d + 1 < dist.get(v, infinity):
                    dist[v] = d + 1
                    heappush(heap, (d + 1, ni, nj, r))

    return abs(si - ti) + abs(sj - tj)

