    size = A * B - 1

    # Row insertion reaches the missing bottom-right cell only by bumping
    # in column A in each of rows 0..B-2. Each lower-left diagonal neighbor
    # must already have been added when its upper-right neighbor is added.
    @lru_cache(None)
    def count(state, gap):
