from math import comb

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count words whose only missing length-M subsequence is X."""
    code = 0
    for value in X:
        if not 1 <= value <= K:
            return 0
        code = code * K + value - 1

    required = K ** M - 1
    # A word has at most C(N,M) distinct subsequences of length M.
    if comb(N, M) < required:
        return 0

    # Every constant word other than X must occur.
    if len(set(X)) != 1 and N < K * M:
        return 0
    if len(set(X)) == 1 and N < (K - 1) * M:
        return 0

    # Each layer is a bitset of distinct subsequences of that length,
    # encoded as base-K integers. Merge prefixes with identical layers.
    initial = (0,) * (M + 1)
    states = {initial: 1}
    target = 1 << code

    for used in range(N):
        remaining = N - used - 1
        nxt = {}
        for layers, ways in states.items():
            for symbol in range(K):
                updated = list(layers)
                for length in range(min(M, used + 1), 0, -1):
                    if length == 1:
                        additions = 1 << symbol
                    else:
                        prefixes = layers[length - 1]
                        additions = 0
                        while prefixes:
                            bit = prefixes & -prefixes
                            prefix_code = bit.bit_length() - 1
                            additions |= 1 << (prefix_code * K + symbol)
                            prefixes -= bit
                    updated[length] |= additions

                state = tuple(updated)
                if state[M] & target:
                    continue
                missing = K ** M - state[M].bit_count()
                if remaining * (K ** (M - 1)) < missing - 1:
                    continue
                nxt[state] = (nxt.get(state, 0) + ways) % MOD
        states = nxt
        if not states:
            return 0

    target_mask = 1 << code
    full_mask = (1 << (K ** M)) - 1
    return sum(
        ways for layers, ways in states.items()
        if (full_mask ^ layers[M]) == target_mask
    ) % MOD

from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """ Count the number of length-M sequences of positive integers whose product is a "good integer" not exceeding N.

    A positive integer n is called a "good integer" if and only if the sum of its positive divisors is divisible by 3.

    The result should be returned modulo 998244353.

    Args:
        N: Upper bound for the product of elements in the sequence (1 <= N <= 10^10)
        M: Length of the sequences (1 <= M <= 10^5)

    Returns:
        The number of valid sequences modulo 998244353

    >>> count_good_sequences(10, 1)
    5
    >>> count_good_sequences(4, 2)
    2
    >>> count_good_sequences(370, 907)
    221764640
    """
    if N < 2:
        return 0
    root = isqrt(N)
    sieve = bytearray(b"\x01") * (root + 1)
    sieve[0] = 0
    if root:
        sieve[1] = 0
    primes = []
    for p in range(2, root + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= root:
                sieve[p * p:root + 1:p] = b"\x00" * (((root - p * p) // p) + 1)
    # Min_25 sieve for the prime counting functions pi(x; 3, 1) and
    # pi(x; 3, 2). The quotient set contains every floor(N/k) used later.
    quotient = []
    k = 1
    while k <= N:
        v = N // k
        quotient.append(v)
        k = N // v + 1
    quotient.sort()
    index = {v: i for i, v in enumerate(quotient)}
    g1 = [(v + 2) // 3 for v in quotient]  # positive integers == 1 mod 3
    g2 = [(v + 1) // 3 for v in quotient]  # positive integers == 2 mod 3
    count1 = 0
    count2 = 0
    for p in primes:
        if p % 3 == 1:
            base1, base2 = 1 + count1, count2
            count1 += 1
        elif p % 3 == 2:
            base1, base2 = 1 + count1, count2
            count2 += 1
        else:
            base1, base2 = 1 + count1, count2
        pp = p * p
        for v in reversed(quotient):
            if v < pp:
                break
            j = index[v // p]
            i = index[v]
            if p % 3 == 1:
                g1[i] -= g1[j] - base1
                g2[i] -= g2[j] - base2
            elif p % 3 == 2:
                g1[i] -= g2[j] - base2
                g2[i] -= g1[j] - base1
    small_pi = [0] * (root + 1)
    small_pi1 = [0] * (root + 1)
    small_pi2 = [0] * (root + 1)
    pi1 = pi2 = 0
    j = 0
    for x in range(root + 1):
        if j < len(primes) and primes[j] == x:
            if x % 3 == 1:
                pi1 += 1
            elif x % 3 == 2:
                pi2 += 1
            j += 1
        small_pi[x] = pi1 + pi2 + (1 if x >= 3 else 0)
        small_pi1[x] = pi1
        small_pi2[x] = pi2
    def prime_counts(x):
        if x <= root:
            return small_pi1[x], small_pi[x]
        i = index[x]
        return g1[i] - 1, g1[i] + g2[i] - 1 + (1 if x >= 3 else 0)
    choose = [1] * (N.bit_length() + 1)
    for e in range(1, len(choose)):
        choose[e] = choose[e - 1] * (M + e - 1) % MOD
        choose[e] = choose[e] * pow(e, MOD - 2, MOD) % MOD
    def prime_weight_sum(x, allowed):
        if x < 2:
            return 0
        n1, nt = prime_counts(x)
        return M * (n1 + (1 if x >= 3 else 0) if allowed else nt) % MOD
    def summatory(allowed):
        @lru_cache(maxsize=None)
        def F(x, start):
            if x < 2:
                return 1
            p0 = primes[start] if start < len(primes) else root + 1
            if p0 * p0 > x:
                # Only 1 and a single prime can occur.
                if p0 <= root:
                    lower = prime_weight_sum(p0 - 1, allowed)
                else:
                    lower = prime_weight_sum(root, allowed)
                return (1 + prime_weight_sum(x, allowed) - lower) % MOD
            ans = 1
            i = start
            while i < len(primes):
                p = primes[i]
                if p * p > x:
                    break
                power = p
                e = 1
                while power <= x:
                    valid = True
                    if allowed:
                        if p % 3 == 1 and e % 3 == 2:
                            valid = False
                        elif p % 3 == 2 and e & 1:
                            valid = False
                    if valid:
                        t = x // power
                        nextp = primes[i + 1] if i + 1 < len(primes) else root + 1
                        if t < nextp * nextp:
                            tail = 1
                            if t >= p:
                                tail += prime_weight_sum(t, allowed) - prime_weight_sum(p, allowed)
                            tail %= MOD
                        else:
                            tail = F(t, i + 1)
                        ans = (ans + choose[e] * tail) % MOD
                    if power > x // p:
                        break
                    power *= p
                    e += 1
                i += 1
            # A prime greater than sqrt(x) can only occur alone.
            r = isqrt(x)
            ans += prime_weight_sum(x, allowed) - prime_weight_sum(r, allowed)
            return ans % MOD
        return F(N, 0)
    total = summatory(False)
    no_zero_local_factor = summatory(True)
    return (total - no_zero_local_factor) % MOD

